import pathlib,sqlite3,json,sys
root=pathlib.Path(r"{data_dir}")/"grokbot"
print("corpus folder (zip THIS folder for the corpus-fix step):", root)
std=root/"documents"/"standards"
stems=sorted(d.name for d in std.iterdir() if d.is_dir()) if std.is_dir() else []
print()
print("== converted BIS documents (documents/standards/<STEM>) ==")
print("  document folders:", len(stems))
idx=root/"indexes"/"documents.json"
meta={}
if idx.is_file():
    d=json.loads(idx.read_text(encoding="utf-8"))
    rows=d if isinstance(d,list) else list(d.values())
    for r in rows:
        if isinstance(r,dict) and r.get("id"): meta[r["id"]]=r
for s in stems:
    r=meta.get(s) or {}
    print(f"   - {s:26} edition {str(r.get('edition') or '?'):12} {str(r.get('collection_name') or ''):32} quality {r.get('quality') or '(not indexed)'}")
    for k in (r.get("known_defects") or [])[:3]: print("       !", k[:110])
print()
print("== search index ==")
f=root/"search"/"spec_fts.sqlite"
if f.is_file():
    try:
        c=sqlite3.connect(f"file:{f}?mode=ro", uri=True); n=c.execute("select count(*) from spec_fts").fetchone()[0]
        print(f"  spec_fts.sqlite  {n:>7} rows   the IS documents")
    except Exception as e: print(f"  spec_fts.sqlite  present but unreadable: {e}")
else:
    print("  spec_fts.sqlite  MISSING -- run Rebuild index")
print("  (no OpenSees / worked-example collections: the India corpus serves the IS documents only)")
v=root/"indexes"/"validate_corpus.json"
if v.is_file():
    try:
        vr=json.loads(v.read_text(encoding="utf-8"))
        print("  last Validate corpus:", "PASS" if vr.get("passed") else "FAIL")
    except Exception: pass
print()
missing=[s for s in stems if s not in meta]
if missing: print("NOTE: folders not in indexes/documents.json (run Rebuild index):", ", ".join(missing))
if not stems:
    print("The corpus is EMPTY. The hub ships no standard text: build it from BIS PDFs you licensed yourself.")
    print("  1. first pass: Admin -> Standards (a folder of PDFs) or Convert (one PDF), then Rebuild index, Validate corpus")
    print("  2. corpus fix: zip the folder above with your PDFs and CORPUS_FIX_LLM_INSTRUCTIONS.md (hub repository root)")
    print("     and give them to a frontier LLM agent with code execution; it returns a fixed corpus zip")
    print("  3. Import fixed corpus (this module): backs up, replaces, rebuilds the index and validates")
elif not f.is_file():
    print("NEXT: run Rebuild index, then Validate corpus")
else:
    print("IS corpus present. The design agents ground their clauses here (RAG_API_URL).")
